{
  "items": [
    {
      "name": "Function.forall_isFixedPt_iff",
      "module_name": "Mathlib.Dynamics.FixedPoints.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u} {f : α → α}, (∀ (x : α), Function.IsFixedPt f x) ↔ f = id"
    },
    {
      "name": "LinearMap.id_apply",
      "module_name": "Mathlib.Algebra.Module.LinearMap.Defs",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_8} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] (x : M),\n  LinearMap.id x = x"
    },
    {
      "name": "LinearMap.id'_apply",
      "module_name": "Mathlib.Algebra.Module.LinearMap.Defs",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_8} [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] {σ : R →+* R}\n  [inst_3 : RingHomId σ] (x : M), LinearMap.id' x = x"
    },
    {
      "name": "FunOnFinite.linearMap_id",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.Pi",
      "kind": "theorem",
      "type": "∀ (R : Type u_5) (M : Type u_6) [inst : Semiring R] [inst_1 : AddCommMonoid M] [inst_2 : Module R M] (X : Type u_7)\n  [inst_3 : Finite X], FunOnFinite.linearMap R M id = LinearMap.id"
    },
    {
      "name": "LinearMap.comp_id",
      "module_name": "Mathlib.Algebra.Module.LinearMap.Defs",
      "kind": "theorem",
      "type": "∀ {R₂ : Type u_3} {R₃ : Type u_4} {M₂ : Type u_10} {M₃ : Type u_11} [inst : Semiring R₂] [inst_1 : Semiring R₃]\n  [inst_2 : AddCommMonoid M₂] [inst_3 : AddCommMonoid M₃] {module_M₂ : Module R₂ M₂} {module_M₃ : Module R₃ M₃}\n  {σ₂₃ : R₂ →+* R₃} (f : M₂ →ₛₗ[σ₂₃] M₃), f ∘ₛₗ LinearMap.id = f"
    }
  ]
}

